#!/bin/sh
# Writes Shared/Secrets.swift (git-ignored) with the server's URL. The app signs in like the
# website does, then gets that person's widget token from the server, so one build fits everyone.
set -e
cd "$(dirname "$0")"
: "${READING_SERVER:?set READING_SERVER to the server URL, e.g. https://read.example.com}"
cat > Shared/Secrets.swift <<SWIFT
// Generated by make-secrets.sh. Do not commit.
enum Secrets {
    static let serverURL = "$READING_SERVER"
}
SWIFT
